def trie_ops(ops):
    root = {}
    out = []
    for op in ops:
        node = root
        if op[0] == 'insert':
            for c in op[1]:
                node = node.setdefault(c, {})
            node['$'] = True
        else:
            ok = True
            for c in op[1]:
                if c not in node:
                    ok = False
                    break
                node = node[c]
            out.append(ok and (op[0] == 'starts_with' or '$' in node))
    return out
